function formatMoney(value: number) {
  return `$${Math.round(value).toLocaleString()}`
}

function MiniSparkline({ color = '#2563ff', down = false }: { color?: string; down?: boolean }) {
  return <svg className="sparkline" viewBox="0 0 120 36" preserveAspectRatio="none"><path d={down ? 'M1 8 C12 14, 15 10, 27 16 S45 12, 58 20 S73 18, 87 27 S103 24, 119 31' : 'M1 29 C12 25, 16 27, 28 23 S43 26, 55 17 S68 20, 80 15 S99 9, 119 3'} fill="none" stroke={color} strokeWidth="2.2" strokeLinecap="round" /></svg>
}

function HealthDonut({ score = 84 }: { score?: number }) {
  return <div className="health-donut" style={{ '--score': `${score * 3.6}deg` } as React.CSSProperties}><div><strong>{score}</strong><small>/ 100</small></div></div>
}

function BarChart({ compact = false }: { compact?: boolean }) {
  const bars = [38, 48, 44, 60, 54, 66, 58, 74, 69, 86, 79, 95]
  return <div className={`bar-chart ${compact ? 'compact' : ''}`}><div className="chart-y-labels"><span>$900k</span><span>$600k</span><span>$300k</span><span>$0</span></div><div className="chart-grid"><div className="grid-line" /><div className="grid-line" /><div className="grid-line" /><div className="grid-line" /><div className="bar-items">{bars.map((height, i) => <div className="bar-wrap" key={i}><div className="bar" style={{ height: `${height}%` }} />{!compact && <span>{['Nov', 'Dec', 'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct'][i]}</span>}</div>)}</div></div></div>
}

function LineChartGraphic() {
  return <div className="line-chart"><div className="line-y"><span>$900k</span><span>$600k</span><span>$300k</span><span>$0</span></div><svg viewBox="0 0 720 220" preserveAspectRatio="none"><defs><linearGradient id="lineFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#2563ff" stopOpacity=".18" /><stop offset="1" stopColor="#2563ff" stopOpacity="0" /></linearGradient></defs><path d="M0 186 L72 165 L145 171 L216 135 L288 145 L360 113 L432 124 L504 88 L576 76 L648 53 L720 28 L720 220 L0 220Z" fill="url(#lineFill)" /><path d="M0 186 L72 165 L145 171 L216 135 L288 145 L360 113 L432 124 L504 88 L576 76 L648 53 L720 28" fill="none" stroke="#2563ff" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" />{[0, 72, 145, 216, 288, 360, 432, 504, 576, 648, 720].map((x, i) => <circle key={i} cx={x} cy={[186, 165, 171, 135, 145, 113, 124, 88, 76, 53, 28][i]} r="4" fill="white" stroke="#2563ff" strokeWidth="2" />)}</svg><div className="line-x"><span>Nov</span><span>Dec</span><span>Jan</span><span>Feb</span><span>Mar</span><span>Apr</span><span>May</span><span>Jun</span><span>Jul</span><span>Aug</span><span>Sep</span><span>Oct</span></div></div>
}

function useSyntheticOverview() {
  const [overview, setOverview] = useState<SyntheticOverview>()
  useEffect(() => { void syntheticApi.overview().then(setOverview).catch(() => undefined) }, [])
  return overview
}

